<template><div><section class="panel"><div class="panel-title"><h2>{{$t("药品处方与发药")}}</h2><el-button size="small" icon="el-icon-refresh" @click="load">{{$t("刷新")}}</el-button></div><div class="toolbar"><el-input v-model.trim="q" clearable :placeholder="$t('患者姓名 / 病历号')" @keyup.enter.native="load"/><el-button @click="load">{{$t("查询")}}</el-button></div><el-table :data="items" stripe v-loading="loading"><el-table-column prop="case_number" :label="$t('病历号')" min-width="120"/><el-table-column prop="real_name" :label="$t('患者')" min-width="90"/><el-table-column prop="drug_name" :label="$t('药品')" min-width="130"/><el-table-column prop="quantity" :label="$t('数量')" width="75"/><el-table-column prop="dosage" :label="$t('用量')" min-width="90"/><el-table-column :label="$t('费用状态')" width="100"><template slot-scope="s">{{$t(status(s.row.payment_status))}}</template></el-table-column><el-table-column :label="$t('药品状态')" width="100"><template slot-scope="s"><el-tag size="small" :type="s.row.status==='DISPENSED'?'success':'info'">{{$t(status(s.row.status))}}</el-tag></template></el-table-column><el-table-column v-if="canEdit" :label="$t('操作')" width="130"><template slot-scope="s"><el-button v-if="s.row.status==='PAID'" type="text" @click="operate(s.row,'dispense')">{{$t("确认发药")}}</el-button><el-button v-if="s.row.status==='DISPENSED'" type="text" @click="operate(s.row,'return')">{{$t("办理退药")}}</el-button></template></el-table-column></el-table></section><section class="panel"><div class="panel-title"><h2>{{$t("药库管理")}}</h2><el-button v-if="canEdit" type="primary" icon="el-icon-plus" @click="addNew">{{$t("录入新药")}}</el-button></div><div class="toolbar"><el-input v-model.trim="drugQuery" clearable :placeholder="$t('药品名称 / 编码')" @keyup.enter.native="loadDrugs"/><el-button @click="loadDrugs">{{$t("查询药库")}}</el-button></div><el-table :data="drugs" stripe><el-table-column prop="drug_code" :label="$t('药品编码')"/><el-table-column prop="drug_name" :label="$t('药品名')"/><el-table-column :formatter="localizedCell" prop="unit" :label="$t('单位')"/><el-table-column prop="unit_price" :label="$t('单价')"/><el-table-column prop="stock" :label="$t('可用库存')"><template slot-scope="s"><strong :class="s.row.stock<10?'status-red':'status-green'">{{$t(s.row.stock)}}</strong></template></el-table-column><el-table-column v-if="canEdit" :label="$t('操作')" width="110"><template slot-scope="s"><el-button type="text" @click="adjust(s.row)">{{$t("库存调整")}}</el-button><el-button type="text" @click="editDrug(s.row)">{{$t("编辑")}}</el-button></template></el-table-column></el-table></section><el-dialog :title="$t(editingDrug?'编辑药品信息':'录入新药')" :visible.sync="drugDialog" append-to-body width="570px"><el-form label-position="top"><div class="form-grid"><el-form-item :label="$t('药品编码')" required><el-input v-model="drugForm.code" :disabled="!!editingDrug" maxlength="32"/></el-form-item><el-form-item :label="$t('药品名称')" required><el-input v-model="drugForm.name" maxlength="120"/></el-form-item><el-form-item :label="$t('包装单位')" required><el-input v-model="drugForm.unit" maxlength="30"/></el-form-item><el-form-item :label="$t('生产厂家')"><el-input v-model="drugForm.producer" maxlength="120"/></el-form-item><el-form-item :label="$t('单价（元）')" required><el-input-number v-model="drugForm.price" :min="0" :precision="2" :step="0.5"/></el-form-item><el-form-item v-if="!editingDrug" :label="$t('期初库存')"><el-input-number v-model="drugForm.stock" :min="0" :max="1000000"/></el-form-item></div></el-form><span slot="footer"><el-button @click="drugDialog=false">{{$t("取消")}}</el-button><el-button type="primary" :loading="savingDrug" @click="saveDrug">{{$t("确认保存")}}</el-button></span></el-dialog></div></template>
<script>import api from '../api';export default{name:'Pharmacy',props:['user'],data(){return{q:'',drugQuery:'',items:[],drugs:[],loading:false,drugDialog:false,editingDrug:null,savingDrug:false,drugForm:{code:'',name:'',unit:'盒',producer:'',price:0,stock:0}}},computed:{canEdit(){return['ADMIN','PHARMACIST'].includes(this.user.role)}},created(){this.load();this.loadDrugs()},methods:{addNew(){this.editingDrug=null;this.drugForm={code:'',name:'',unit:'盒',producer:'',price:0,stock:0};this.drugDialog=true},editDrug(row){this.editingDrug=row.id;this.drugForm={code:row.drug_code,name:row.drug_name,unit:row.unit,producer:row.producer||'',price:Number(row.unit_price),stock:row.stock};this.drugDialog=true},async saveDrug(){if(!this.drugForm.code||!this.drugForm.name||!this.drugForm.unit)return this.$message.warning('请填写必填信息');try{await this.$confirm('确认保存药品信息？','保存确认',{type:'warning'})}catch{return}this.savingDrug=true;try{if(this.editingDrug)await api.put(`/drugs/${this.editingDrug}`,this.drugForm);else await api.post('/drugs',this.drugForm);this.$message.success('药品信息已保存');this.drugDialog=false;this.loadDrugs()}catch(e){this.$message.error(e.message)}finally{this.savingDrug=false}},status(v){return{UNPAID:'待缴费',PAID:'已缴费 / 待发',DISPENSED:'已发药',RETURNED:'已退药',REFUNDED:'已退费'}[v]||v},async load(){this.loading=true;try{this.items=await api.get('/prescriptions',{params:{q:this.q}})}catch(e){this.$message.error(e.message)}finally{this.loading=false}},async loadDrugs(){try{this.drugs=await api.get('/drugs',{params:{q:this.drugQuery}})}catch(e){this.$message.error(e.message)}},async operate(row,action){let label=action==='dispense'?'发药（将扣减库存）':'退药（将返还库存）';try{await this.$confirm(`确定为 ${row.real_name} 办理 ${label}？`,'药房操作确认',{type:'warning'})}catch{return}try{await api.post(`/prescriptions/${row.item_id}/${action}`);this.$message.success('处理成功');this.load();this.loadDrugs()}catch(e){this.$message.error(e.message)}},async adjust(row){let input;try{input=await this.$prompt(`为「${row.drug_name}」调整库存：正数入库，负数出库。当前库存 ${row.stock}`,'调整药品库存',{inputPattern:/^[+-]?[1-9]\d*$/,inputErrorMessage:'请输入非零整数',confirmButtonText:'确认调整',cancelButtonText:'取消'})}catch{return}try{await api.post(`/drugs/${row.id}/stock`,{delta:input.value});this.$message.success('库存已更新');this.loadDrugs()}catch(e){this.$message.error(e.message)}}}}</script>
